BYTES = {"fp32": 4, "fp16": 2, "int8": 1, "int4": 0.5}

def weights_gb(params_billion, dtype):
    return params_billion * 1e9 * BYTES[dtype] / 1024**3

for dtype in ["fp32", "fp16", "int4"]:
    print(dtype, round(weights_gb(7, dtype), 1), "GB")

embed_model_m = 110
print("embedder fp32:", round(weights_gb(embed_model_m / 1000, "fp32"), 2), "GB")

def pick_runtime(job):
    if job["gpu"]:
        return "ECS/EC2 GPU or managed endpoint"
    if job["max_seconds"] > 900 or job["image_gb"] > 10:
        return "ECS Fargate"
    if job["streaming"]:
        return "ECS Fargate"
    return "Lambda"

jobs = {
    "embed-batch-nightly": {"gpu": False, "max_seconds": 3600, "image_gb": 2, "streaming": False},
    "classify-review": {"gpu": False, "max_seconds": 5, "image_gb": 1, "streaming": False},
    "chat-api": {"gpu": False, "max_seconds": 60, "image_gb": 1, "streaming": True},
    "self-hosted-llm": {"gpu": True, "max_seconds": 60, "image_gb": 20, "streaming": True},
}
for name, job in jobs.items():
    print(f"{name}: {pick_runtime(job)}")
